-- Content: Testbench for ALU
library ieee;
use ieee.std_logic_1164.all;
use ieee.numeric_std.all;
use ieee.math_real.uniform;
use ieee.math_real.floor;
use work.riscv_types.all;
library std;
use std.textio.all;
use std.env.finish;
entity alu_tb is
end alu_tb;
-- Architecture testing of alu_tb: testing calculations
architecture testing of alu_tb is
    -- clock definition
    signal clk          : std_logic;
    constant clk_period : time := 10 ns;
    -- Inputs
    signal alu_opc_tb : aluOP;
    signal input1_tb  : word;
    signal input2_tb  : word;
    -- Outputs
    signal result_tb : word;
    signal verify : word;
begin
    -- Entity work.alu(implementation): Init of Unit Under Test
    uut : entity work.alu(implementation)
        port map (
            Operation_Code => alu_opc_tb,
            Operand_1  => input1_tb,
            Operand_2  => input2_tb,
            Result  => result_tb
            );
    -- Process clk_process  operating the clock
    clk_process : process               -- runs only, when  changed
    begin
        clk <= '0';
        wait for clk_period/2;
        clk <= '1';
        wait for clk_period/2;
    end process;
    -- Process stim_proc  control device for uut
    stim_proc : process                 -- runs only, when  changed
        -- Text I/O
        variable lineBuffer : line;
    begin
        -- wait for the rising edge
        wait until rising_edge(clk);
        -- Print the top element
        write(lineBuffer, string'("Start the simulator"));
        writeline(output, lineBuffer);
      input1_tb <= std_logic_vector(to_unsigned(0, 32));
      input2_tb <= std_logic_vector(to_unsigned(0, 32));
      alu_opc_tb <= uNop;
      wait for 10 ns;
      assert result_tb = x"00000000" report "Nop Error" severity failure;
      alu_opc_tb <= uAdd;
      verify <= x"00000000";
      wait for 10 ns;
      assert result_tb = verify report "Add Error" severity failure;
      alu_opc_tb <= uSub;
      verify <= x"00000000";
      wait for 10 ns;
      assert result_tb = verify report "Sub Error" severity failure;
      alu_opc_tb <= uSLL;
      verify <= x"00000000";
      wait for 10 ns;
      assert result_tb = verify report "SLL Error" severity failure;
      alu_opc_tb <= uSLT;
      verify <= x"00000000";
      wait for 10 ns;
      assert result_tb = verify report "SLT Error" severity failure;
      alu_opc_tb <= uSLTU;
      verify <= x"00000000";
      wait for 10 ns;
      assert result_tb = verify report "SLTU Error" severity failure;
      alu_opc_tb <= uXOR;
      verify <= x"00000000";
      wait for 10 ns;
      assert result_tb = verify report "XOR Error" severity failure;
      alu_opc_tb <= uSRL;
      verify <= x"00000000";
      wait for 10 ns;
      assert result_tb = verify report "SRL Error" severity failure;
      alu_opc_tb <= uOR;
      verify <= x"00000000";
      wait for 10 ns;
      assert result_tb = verify report "OR Error" severity failure;
      alu_opc_tb <= uAND;
      verify <= x"00000000";
      wait for 10 ns;
      assert result_tb = verify report "AND Error" severity failure;
      input1_tb <= std_logic_vector(to_unsigned(0, 32));
      input2_tb <= std_logic_vector(to_unsigned(1, 32));
      alu_opc_tb <= uNop;
      wait for 10 ns;
      assert result_tb = x"00000000" report "Nop Error" severity failure;
      alu_opc_tb <= uAdd;
      verify <= x"00000001";
      wait for 10 ns;
      assert result_tb = verify report "Add Error" severity failure;
      alu_opc_tb <= uSub;
      verify <= x"ffffffff";
      wait for 10 ns;
      assert result_tb = verify report "Sub Error" severity failure;
      alu_opc_tb <= uSLL;
      verify <= x"00000000";
      wait for 10 ns;
      assert result_tb = verify report "SLL Error" severity failure;
      alu_opc_tb <= uSLT;
      verify <= x"00000001";
      wait for 10 ns;
      assert result_tb = verify report "SLT Error" severity failure;
      alu_opc_tb <= uSLTU;
      verify <= x"00000001";
      wait for 10 ns;
      assert result_tb = verify report "SLTU Error" severity failure;
      alu_opc_tb <= uXOR;
